import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        bound(amount, 1, type(uint128).max);
        // Make the contract's balance strictly less than the requested amount:
        // the payout can never succeed, so a correct transfer MUST revert.
        vm.deal(address(c), amount - 1);

        bool ok;
        try c.sendTo(address(this), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an underfunded payout always reverts.
        assertTrue(!ok, "underfunded sendTo must revert");
    }
}

